using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m, b;
    if (!(cin >> m >> b)) return 0;

    long long ans = 0;

    // Iterate over possible y-intercepts (integer y0 from 0 to b)
    for (long long y0 = 0; y0 <= b; ++y0) {
        long long x0 = (b - y0) * m; // max x for this y0 from line x/m + y = b

        long long n = x0 + 1; // number of x from 0 to x0
        long long sumX = x0 * (x0 + 1) / 2; // sum of x from 0 to x0

        // For each y from 0 to y0, sum over x from 0 to x0 of (x + y)
        // Total bananas:
        // sum_y [ sum_x (x + y) ]
        // = sum_y [ sum_x x + (x0+1)*y ]
        // = (y0+1)*sumX + (x0+1)*sum_y y
        long long sumY = y0 * (y0 + 1) / 2;
        long long total = (y0 + 1) * sumX + n * sumY;

        if (total > ans) ans = total;
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m, b;
    if (!(cin >> m >> b)) return 0;

    long long ans = 0;

    // Iterate over possible x2 (right boundary of rectangle)
    for (long long x2 = 0; x2 <= b * m; ++x2) {
        // Maximum y on the line for this x2
        long long y2 = (b * m - x2) / m;
        if (y2 < 0) continue;

        // Sum over x from 0 to x2 of (x + y2) * (y2 + 1)
        // = (y2 + 1) * ( sum_x x + sum_x y2 )
        // sum_x x = x2*(x2+1)/2, sum_x y2 = (x2+1)*y2
        long long n = x2 + 1;
        long long sumx = x2 * (x2 + 1) / 2;
        long long sum = (y2 + 1) * (sumx + n * y2);

        if (sum > ans) ans = sum;
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m, b;
    if (!(cin >> m >> b)) return 0;

    long long ans = 0;

    // Iterate over possible y2 (top side of rectangle)
    for (long long y2 = 0; y2 <= b; ++y2) {
        // Maximum x2 allowed by the line: x/m + y = b => x = m*(b - y)
        long long x2 = m * (b - y2);
        if (x2 < 0) continue;

        long long n = x2;
        long long k = y2;

        // sum over rectangle: sum_{x=0..n} sum_{y=0..k} (x + y)
        // = sum_{x=0..n} (k+1)*x + sum_{y=0..k} (n+1)*y
        // = (k+1)*n(n+1)/2 + (n+1)*k(k+1)/2
        long long term1 = (k + 1) * n * (n + 1) / 2;
        long long term2 = (n + 1) * k * (k + 1) / 2;
        long long total = term1 + term2;

        if (total > ans) ans = total;
    }

    cout << ans << '\n';
    return 0;
}

